import * as THREE from 'three/webgpu';
import { MeshStandardNodeMaterial, color } from 'three/tsl';
import { gsap } from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'stat-tile-home';
  group.position.set(-2.5, 1.6, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const palette = {
    ink: 0x16161d,
    paper: 0xe8ecf2,
    accent: 0xff2a38,
    surface: 0x0b0b10,
  };

  // Base machined-surface backing plate behind the mesh (fallback surface in case GLB fails/loads late)
  const plateGeo = new THREE.PlaneGeometry(1.6, 1.0);
  const plateMat = new MeshStandardNodeMaterial();
  plateMat.colorNode = color(palette.surface);
  plateMat.metalness = 0.5;
  plateMat.roughness = 0.55;
  const plate = new THREE.Mesh(plateGeo, plateMat);
  plate.position.z = -0.02;
  group.add(plate);

  // Load the gear mesh from GLB (cached loader)
  let gearRoot = null;
  const meshUrl = config?.assets?.meshUrl || '/prism-mock/orrery/meshes/gear-a.glb';

  const gltf = ctx.glbLoader.load ? null : null; // no-op, using promise-based API below safely
  // ctx.glbLoader returns cached resources synchronously via .get or similar; assume .load returns cached GLTF object synchronously when pre-cached, otherwise a promise handled internally by ctx.
  try {
    const loaded = ctx.glbLoader(meshUrl);
    if (loaded && loaded.scene) {
      gearRoot = loaded.scene.clone(true);
      gearRoot.scale.set(0.5, 0.5, 0.5);
      gearRoot.position.set(0, 0, 0.05);
      group.add(gearRoot);
    }
  } catch (e) {
    // If loader throws synchronously due to not-yet-cached, silently skip; scene will still render base plate.
  }

  // Value + label text (MSDF)
  const valueText = createTextMesh({
    text: config?.textContent?.value || '128',
    font: 'display',
    weight: 600,
    size: 0.34,
    color: palette.paper,
    ctx,
  });
  valueText.position.set(-0.6, 0.15, 0.1);
  group.add(valueText);

  const labelText = createTextMesh({
    text: config?.textContent?.label || 'ATELIER PIECES',
    font: 'text',
    weight: 400,
    size: 0.09,
    color: palette.paper,
    ctx,
  });
  labelText.position.set(-0.6, -0.15, 0.1);
  group.add(labelText);

  // Accent edge frame (thin line mesh) for focus state, hidden by default
  const edgeGeo = new THREE.EdgesGeometry(new THREE.PlaneGeometry(1.6, 1.0));
  const edgeMat = new THREE.LineBasicMaterial({ color: palette.accent, transparent: true, opacity: 0 });
  const edge = new THREE.LineSegments(edgeGeo, edgeMat);
  edge.position.z = 0.03;
  group.add(edge);

  // Apply cinematic primitives from config
  const primitivesConfig = config.cinematicPrimitives || [];
  for (const prim of primitivesConfig) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      fn(group, prim.params || {});
    }
  }

  // Interaction state
  let hoverTl = null;
  let pressTl = null;
  const baseY = group.position.y;

  function onHoverEnter() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, { y: baseY + 0.15, duration: 0.7, ease: 'power3.out' });
    hoverTl.to(edgeMat, { opacity: 1, duration: 0.3, ease: 'power2.out' }, 0);
  }

  function onHoverLeave() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, { y: baseY, duration: 0.7, ease: 'power3.out' });
    hoverTl.to(edgeMat, { opacity: 0, duration: 0.3, ease: 'power2.out' }, 0);
  }

  function onClick() {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' });
    pressTl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'back.out' });

    if (group.userData.emit) {
      group.userData.emit('hub-home.select', { source: 'stat-tile-home' });
    }
  }

  group.userData.handlers = {
    hover: onHoverEnter,
    hoverEnd: onHoverLeave,
    click: onClick,
  };

  group.userData.cleanup = function cleanup() {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();

    plateGeo.dispose();
    plateMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();

    if (gearRoot) {
      gearRoot.traverse((obj) => {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) {
          if (Array.isArray(obj.material)) {
            obj.material.forEach((m) => m.dispose());
          } else {
            obj.material.dispose();
          }
        }
      });
    }

    if (valueText.userData && typeof valueText.userData.dispose === 'function') {
      valueText.userData.dispose();
    }
    if (labelText.userData && typeof labelText.userData.dispose === 'function') {
      labelText.userData.dispose();
    }
  };

  return group;
}
